package app.truemotion.vector;
import java.io.*;
import java.util.*;
import org.w3c.dom.Element;
/** Sparrow/TextureAtlas XML coordinates and frame registration. */
public final class VectorAtlas {
    public static final class Frame {public String name;public int x,y,width,height,frameX,frameY,frameWidth,frameHeight;}
    public String imagePath="";public double fps=30;public final ArrayList<Frame> frames=new ArrayList<Frame>();
    public static VectorAtlas read(byte[] xml)throws Exception{Element root=VectorXfl.parse(xml);if(!VectorXfl.tag(root).equals("TextureAtlas"))throw new IOException("Expected TextureAtlas / Sparrow XML");VectorAtlas atlas=new VectorAtlas();atlas.imagePath=root.getAttribute("imagePath");atlas.fps=VectorXfl.number(root,"fps",30);for(Element e:VectorXfl.children(root,"SubTexture")){if("true".equals(e.getAttribute("rotated")))throw new IOException("Rotated atlas entries are not supported");Frame f=new Frame();f.name=e.getAttribute("name");f.x=(int)VectorXfl.number(e,"x",0);f.y=(int)VectorXfl.number(e,"y",0);f.width=(int)VectorXfl.number(e,"width",0);f.height=(int)VectorXfl.number(e,"height",0);f.frameX=(int)VectorXfl.number(e,"frameX",0);f.frameY=(int)VectorXfl.number(e,"frameY",0);f.frameWidth=(int)VectorXfl.number(e,"frameWidth",f.width);f.frameHeight=(int)VectorXfl.number(e,"frameHeight",f.height);if(f.x<0||f.y<0||f.width<1||f.height<1||f.frameWidth<1||f.frameHeight<1||f.frameWidth>16384||f.frameHeight>16384)throw new IOException("Invalid atlas coordinates");atlas.frames.add(f);}if(atlas.frames.isEmpty())throw new IOException("No SubTexture frames");return atlas;}
    public VectorDocument document(VectorImage image,double fallbackFps){VectorDocument doc=new VectorDocument(1,1,fps>0&&fps<=1000?fps:fallbackFps,frames.size());doc.images.put(image.id,image);VectorDocument.Track track=doc.tracks.get(0);track.name="Sprites";track.keys.clear();for(Frame f:frames){doc.width=Math.max(doc.width,f.frameWidth);doc.height=Math.max(doc.height,f.frameHeight);if((long)f.x+f.width>image.width||(long)f.y+f.height>image.height)throw new IllegalArgumentException("Atlas frame exceeds PNG page");}for(int i=0;i<frames.size();i++){Frame f=frames.get(i);VectorDocument.Shape s=new VectorDocument.Shape();s.name=f.name;s.image=image.id;s.imageRect=new int[]{f.x,f.y,f.width,f.height};s.imageFrame=new int[]{f.frameWidth,f.frameHeight,f.frameX,f.frameY};s.x=doc.width/2d;s.y=doc.height/2d;s.strokeWidth=0;s.fill=0;VectorDocument.Cel cel=new VectorDocument.Cel();cel.shapes.add(s);track.keys.put(i,cel);}doc.validate();return doc;}
    public static String header(String path,double fps){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<TextureAtlas imagePath=\""+VectorDocument.escape(path)+"\" fps=\""+VectorDocument.n(fps)+"\">\n";}
    public static String entry(String name,int x,int y,int width,int height){return "  <SubTexture name=\""+VectorDocument.escape(name)+"\" x=\""+x+"\" y=\""+y+"\" width=\""+width+"\" height=\""+height+"\" frameX=\"0\" frameY=\"0\" frameWidth=\""+width+"\" frameHeight=\""+height+"\"/>\n";}
}
